CREATE FUNCTION dbo.fn_FormatCustomerName(@FirstName NVARCHAR(100), @LastName NVARCHAR(100))
RETURNS NVARCHAR(201)
AS
BEGIN
    RETURN ISNULL(@LastName, '') + ', ' + ISNULL(@FirstName, '');
END;

