CREATE OR REPLACE FUNCTION dbo.fn_FormatCustomerName(
    p_FirstName VARCHAR(100),
    p_LastName VARCHAR(100)
)
RETURNS VARCHAR(201)
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    RETURN COALESCE(p_LastName, '') || ', ' || COALESCE(p_FirstName, '');
END;
$$;
